=== prefer-early-return ===
/**
 * prefer-early-return — guard clauses over else branches and wrapped tails.
 *
 * Two shapes are reported:
 *
 * 1. Any `else`. When the consequent terminates (ends in return/throw/
 *    continue/break) the else is pure nesting: de-nest it into a sibling
 *    statement — autofixed, unless the else block declares a binding that
 *    unwrapping could collide with the enclosing scope. When the consequent
 *    does NOT terminate, the branches must become two separate ifs
 *    (`if (x)` / `if (!x)`); that rewrite is left to a human, because the
 *    consequent may have changed the state the negated condition would read.
 *
 * 2. A terminating `if` (no else) whose body outweighs the statements after
 *    it — the whole happy path wrapped in `if (x) {...}` with a dangling
 *    fallback tail. Flip it: `if (!x)` guards the tail, the happy path goes
 *    flat. Detect-only; moving blocks across comments is where codemods eat
 *    code.
 */
const TERMINATORS = new Set([
    "ReturnStatement",
    "ThrowStatement",
    "ContinueStatement",
    "BreakStatement",
]);
const DECLARATIONS = new Set([
    "VariableDeclaration",
    "FunctionDeclaration",
    "ClassDeclaration",
]);
/** A wrapped happy path is only worth flipping when it is a real block. */
const MIN_WRAPPED = 4;
/** True when control cannot flow past this statement into the next sibling. */
function terminates(statement) {
    if (!statement)
        return false;
    if (statement.type === "BlockStatement") {
        return terminates(statement.body[statement.body.length - 1]);
    }
    return TERMINATORS.has(statement.type);
}
/** Like {@link terminates}, but only for leaving the function entirely. */
function exits(statement) {
    if (!statement)
        return false;
    if (statement.type === "BlockStatement") {
        return exits(statement.body[statement.body.length - 1]);
    }
    return (statement.type === "ReturnStatement" || statement.type === "ThrowStatement");
}
function statementCount(statement) {
    return statement.type === "BlockStatement" ? statement.body.length : 1;
}
/** Unwrapping an else block hoists its statements into the enclosing scope; a
 *  top-level declaration there could collide, so those keep a human's eyes. */
function declaresBindings(alternate) {
    if (alternate.type !== "BlockStatement") {
        return DECLARATIONS.has(alternate.type);
    }
    return alternate.body.some((statement) => DECLARATIONS.has(statement.type));
}
function fixUnnecessaryElse(sourceCode, fixer, node) {
    const elseToken = sourceCode.getTokenBefore(node.alternate, (token) => token.type === "Keyword" && token.value === "else");
    // `else if (...)` — dropping the keyword leaves a sibling if.
    if (node.alternate.type === "IfStatement") {
        return fixer.removeRange([elseToken.range[0], node.alternate.range[0]]);
    }
    // `else { ... }` — replace keyword-through-block with the block's body.
    if (node.alternate.type === "BlockStatement") {
        const inner = sourceCode.getText(node.alternate).slice(1, -1).trim();
        return fixer.replaceTextRange([elseToken.range[0], node.alternate.range[1]], inner);
    }
    // `else statement;` — just drop the keyword.
    return fixer.removeRange([elseToken.range[0], node.alternate.range[0]]);
}
/** Shape 1: the report for an if that carries an else. */
function elseDescriptor(sourceCode, node) {
    if (!terminates(node.consequent)) {
        return { node, messageId: "splitIntoTwoIfs" };
    }
    const fixable = !declaresBindings(node.alternate);
    return {
        node: node.alternate,
        messageId: "unnecessaryElse",
        data: { how: "returns" },
        fix: fixable
            ? (fixer) => fixUnnecessaryElse(sourceCode, fixer, node)
            : undefined,
    };
}
function wrapsHappyPath(wrapped, tailLength) {
    return tailLength > 0 && wrapped >= MIN_WRAPPED && wrapped > tailLength;
}
/** Shape 2: the tail length dangling after an if that wraps the happy path,
 *  or null. Only `return`/`throw` wraps qualify — a chunky continue/break
 *  guard in a loop is already guard-shaped, its wrapped block being the
 *  exceptional path — and only a REAL block (≥ MIN_WRAPPED statements)
 *  outweighing its tail is worth a warning. */
function wrappedTailLength(node) {
    if (node.parent.type !== "BlockStatement" || !exits(node.consequent)) {
        return null;
    }
    const siblings = node.parent.body;
    const tailLength = siblings.length - siblings.indexOf(node) - 1;
    return wrapsHappyPath(statementCount(node.consequent), tailLength)
        ? tailLength
        : null;
}
function guardDescriptor(node) {
    const tailLength = wrappedTailLength(node);
    if (tailLength === null)
        return null;
    return { node, messageId: "flipToGuard", data: { tail: String(tailLength) } };
}
export default {
    meta: {
        type: "suggestion",
        fixable: "code",
        docs: {
            description: "Guard clauses over else branches and wrapped tails: de-nest an else after a terminating if, split a non-terminating if/else into two ifs, and flip an if that wraps the whole happy path.",
        },
        messages: {
            unnecessaryElse: "The if branch {{how}}, so this else only nests — de-nest its statements to follow the if.",
            splitIntoTwoIfs: "No else branches: split into two ifs — `if (x)` and `if (!x)` — or restructure so the first branch returns.",
            flipToGuard: "The happy path is wrapped in this if while {{tail}} statement(s) dangle after it — flip to `if (!(…))` guarding the tail and let the happy path run flat.",
        },
        schema: [],
    },
    create(context) {
        const sourceCode = context.sourceCode;
        return {
            IfStatement(node) {
                const descriptor = node.alternate
                    ? elseDescriptor(sourceCode, node)
                    : guardDescriptor(node);
                if (descriptor)
                    context.report(descriptor);
            },
        };
    },
};
=== max-member-chain ===
/**
 * max-member-chain — Law of Demeter. A chain like `a.b.c.d` or `a.b().c.d()`
 * reaches through collaborators the caller has no business knowing; the
 * caller should ask its direct collaborator for what it needs.
 *
 * Depth = number of `MemberExpression` hops from the chain's root. Computed
 * hops (`a[0].b`) and optional hops (`a?.b`) count like any other. Only the
 * OUTERMOST member expression of a chain is reported — an inner one whose
 * parent continues the chain (as the object of another member, or as the
 * callee of a call that is itself continued) is skipped.
 *
 * Exempt:
 *  - the root is `this` / `super`;
 *  - the root is a well-known global (`Math`, `JSON`, `Promise`, `Object`,
 *    `Array`, `Number`, `String`, `Reflect`, `process`, `console`,
 *    `globalThis`, `window`, `document`, `Symbol`, `Date`) or a name listed
 *    in option `allowRoots`;
 *  - every hop after the root is a call (`builder().a().b().c()` fluent
 *    chains return the same kind of thing at each step);
 *  - chains rooted in `import.meta`.
 *
 * Detect-only: the fix is a method on the direct collaborator.
